"""Instruction streams generated by a compiled IRON dispatch library.

Operators that take runtime scalars do not emit one ``.bin``. Their host
library exports ``dispatch_generate``, which writes the transaction for one
scalar set. The NPU package stores one of those transactions per dispatch and
submits it with the same xclbin.
"""

from pathlib import Path

import numpy as np


def generate_dispatch_transaction(library, param_names, values):
    """Return the transaction bytes for one scalar set.

    ``param_names`` is the operator's ``get_dispatch_params()`` order. ``values``
    maps those names to integers. The library is the ``.dll`` or ``.so`` the
    host compile produced.
    """
    from aie.utils.compile.jit._dispatch_bridge import DispatchBridge

    words = DispatchBridge(Path(library), list(param_names)).generate(dict(values))
    return np.ascontiguousarray(words, dtype=np.uint32).tobytes()
